#include <stdio.h>

int main(void) {
    int n, ventas[100], suma = 0, i;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &ventas[i]);
        suma += ventas[i];
    }
    printf("%.2f\n", (float)suma / n);
    return 0;
}

