#include <stdio.h>

int main(void) {
    int n, suma = 0, i;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        suma += x;
    }
    if (n == 0) {
        printf("0.00\n");
    } else {
        printf("%.2f\n", (float)suma / n);
    }
    return 0;
}

