#include <stdio.h>

int main(void) {
    int n, ventas[100], max, i;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &ventas[i]);
    }
    max = ventas[0];
    for (i = 1; i < n; i++) {
        if (ventas[i] > max) {
            max = ventas[i];
        }
    }
    printf("%.1f\n", (float)max);
    return 0;
}

