#include <stdio.h>

int main(void) {
    int n, max;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (i == 0) {
            max = x;
        } else {
            if (x > max) {
                max = x;
            }
        }
    }
    printf("%.1f\n", (float)max);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, contador = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (x > 1000) {
            contador++;
        }
    }
    printf("%d\n", contador);
    return 0;
}
